<script setup lang="ts">
import PmsFormDialog from './PmsFormDialog.vue';import {ref,onMounted} from 'vue';import {pmsApi} from './api';const props=defineProps<{type:string;id:number;csrf?:string;canSubmit?:boolean}>();const data=ref<any>(null),form=ref<any>(null),busy=ref(false),error=ref('');async function load(){data.value=await pmsApi('submissions?type='+props.type+'&id='+props.id);}async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn();await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}async function send(){await run(async()=>{const body=new FormData();body.append('type',props.type);body.append('main_id',String(props.id));body.append('title',form.value.title);body.append('description',form.value.description);if(form.value.file)body.append('file',form.value.file);const r=await pmsApi('submissions',props.csrf,'POST',body);if(!r.status)throw Error(r.message);form.value=null;});}async function status(s:any,e:Event){await run(async()=>{await pmsApi('submissions/status',props.csrf,'POST',{id:s.id,status:(e.target as HTMLSelectElement).value});});}async function remove(id:number){if(confirm('Delete this submission?'))await run(async()=>{const r=await pmsApi('submissions/'+id,props.csrf,'DELETE');if(!r.status)throw Error(r.message);});}onMounted(()=>run(load));
</script><template><section class="card p-3 my-3"><div class="admin-section-heading"><h3>Submissions</h3><button v-if="data?.can_submit" class="button" @click="form={title:'',description:'',file:null}">New submission</button></div><p v-if="error" class="notice admin-error">{{error}}</p><PmsFormDialog v-if="form" title="New submission" centered @close="form=null"><form class="pms-reference-form" @submit.prevent="send"><label class="full-width">Title<input v-model="form.title" required></label><label class="full-width">Description<textarea v-model="form.description"></textarea></label><label class="full-width">Attachment<input type="file" accept=".pdf,.doc,.docx,.zip,.rar,.jpg,.jpeg,.png" @change="form.file=($event.target as HTMLInputElement).files?.[0]"></label><div class="editor-actions"><button class="button primary" :disabled="busy">Submit</button><button type="button" class="button" @click="form=null">Cancel</button></div></form></PmsFormDialog><table class="pms-table"><thead><tr><th>Title</th><th>Description</th><th>Attachment</th><th>Submitted by</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody><tr v-for="s in data?.submissions" :key="s.id"><td>{{s.title}}</td><td>{{s.description}}</td><td><a v-if="s.file_path" :href="s.file_path.startsWith('http')?s.file_path:'/storage/'+s.file_path" target="_blank" rel="noopener">Attachment</a></td><td>{{s.user?.name}}</td><td><select v-if="data.can_manage" :value="s.status" :disabled="busy" @change="status(s,$event)"><option value="pending">Pending</option><option value="approved">Approved</option><option value="rejected">Rejected</option></select><span v-else>{{s.status}}</span></td><td>{{s.created_at}}</td><td><button v-if="data.can_delete" class="button" :disabled="busy" @click="remove(s.id)">Delete</button></td></tr><tr v-if="!data?.submissions.length"><td colspan="7">No submissions yet.</td></tr></tbody></table></section></template>